/**
 * Capture a session's pi ENTRIES as JSON, for use as a test fixture.
 *
 * The conformance corpus under `contracts/conformance/` is generated by the
 * Swift app; this client's fold is additionally checked against a scripted
 * double (`scripts/fake-machine.ts`) whose shape I wrote by reading the
 * extension. Both can be wrong in the same way. A dump from a REAL pi session
 * is the only thing that checks my fold against what the machine actually
 * sends — which is how the double's own lies got found (timestamps inside
 * `message`, an entry that was never written).
 *
 *   npx tsx scripts/dump-entries.ts \
 *     --relay http://mybox.my-tailnet.ts.net:3000 \
 *     --pair  'unbien://pair?t=…&epk=…&n=…&rm=…' \
 *     --out   /tmp/unbien-fixture.json
 *
 * `--watch <seconds>` adds a LIVE-plane capture: after the entry walk, every
 * envelope the machine pushes is appended to `--watch-out` as one JSON per line.
 * That is how you record the shapes an entry log cannot show — an image
 * streaming inside `tool_execution_end`, a `subagents:*` panel, an ask opening
 * live. Drive the session during the window.
 *
 * (`npx tsx`, not `node --experimental-strip-types`: this package writes
 * extensionless-`.js` specifiers for the browser's sake, and Node's type
 * stripping will not resolve them to `.ts`.)
 *
 * Honest limits:
 *  - This process has NO stored device identity (Node has no localStorage), so
 *    every run is a NEW device and needs a FRESH pairing code. That is the
 *    protocol working, not a bug: the machine's code is single-use.
 *  - Whatever the session's rows contain gets written to disk verbatim — prompt
 *    text, tool output, file paths. Treat the output file as containing your
 *    session; keep it out of the repo (`/tmp` by default is deliberate).
 */
import {
  chmodSync,
  existsSync,
  mkdirSync,
  readFileSync,
  writeFileSync,
} from "node:fs"
import { homedir } from "node:os"
import { dirname, join, resolve } from "node:path"
import {
  canonicalizeEd25519PublicKey,
  ed25519KeypairFromSeed,
  encodeEd25519PublicKey,
  generateEd25519Keypair,
  type Ed25519Keypair,
} from "@geohar/un-bien/client"
import { parseInvite } from "../src/invite.js"
import { SessionClient, type RelayRoomList } from "../src/session-client.js"

/**
 * A STANDING device identity, kept on disk like the CLI's
 * `~/.local/state/un-bien/proxy-identity.json`. Without it every run is a brand
 * new device needing a fresh single-use pairing code; with it the machine
 * already trusts this device (its peers.json), so re-dumping any room is one
 * command and no human in the loop.
 *
 * Plaintext on disk, same honest caveat as the browser's localStorage copy: the
 * file is readable to anything with your user, which is why it is chmod 600 and
 * why `/unbien revoke` has to stay easy to reach.
 */
function nodeIdentity(path: string): {
  keypair: Ed25519Keypair
  created: boolean
} {
  if (existsSync(path)) {
    const stored = JSON.parse(readFileSync(path, "utf8")) as { seed?: string }
    if (!stored.seed) throw new Error(`${path} holds no seed`)
    return {
      keypair: ed25519KeypairFromSeed(Buffer.from(stored.seed, "base64")),
      created: false,
    }
  }
  const keypair = generateEd25519Keypair()
  mkdirSync(dirname(path), { recursive: true })
  writeFileSync(
    path,
    JSON.stringify({
      seed: Buffer.from(keypair.secretKey).toString("base64"),
      publicKey: encodeEd25519PublicKey(keypair.publicKey),
    }),
    { mode: 0o600 },
  )
  chmodSync(path, 0o600)
  return { keypair, created: true }
}

function arg(name: string): string | undefined {
  const i = process.argv.indexOf(`--${name}`)
  return i >= 0 ? process.argv[i + 1] : undefined
}

function flag(name: string): boolean {
  return process.argv.includes(`--${name}`)
}

function describeRooms(epk: string, rooms: RelayRoomList): string {
  if (rooms.status !== "ok") return `rooms_check: ${rooms.status}`
  return rooms.rooms
    .map(
      (room) =>
        `  ${room.room_id}${room.name ? ` — ${room.name}` : ""}${
          room.cwd ? ` (${room.cwd})` : ""
        }${room.parent ? " [subagent]" : ""}`,
    )
    .join("\n")
}

async function main(): Promise<number> {
  const relay = arg("relay")
  const pairCode = arg("pair")
  const peerArg = arg("peer")
  if (!relay || (!pairCode && !peerArg)) {
    console.error(
      "usage: dump-entries --relay http://host:3000 (--pair unbien://pair?… | " +
        "--peer <machine epk>) [--room <id>] [--out <path>] [--max-pages N] " +
        "[--identity <path>] [--include-panels] [--watch <secs>]\n" +
        "  --pair pairs (and needs a fresh code, valid 60s unless " +
        "`/unbien pair --ttl 600`); --peer reuses the stored device identity.\n" +
        "  --watch records every envelope pushed after the walk to --watch-out " +
        "(default /tmp/unbien-live.jsonl): the live plane, which get_entries " +
        "cannot show.",
    )
    return 2
  }
  const out = resolve(arg("out") ?? "/tmp/unbien-fixture.json")
  const maxPages = Number(arg("max-pages") ?? 200)
  const identityPath = resolve(
    arg("identity") ??
      join(homedir(), ".local", "state", "un-bien", "web-dump-identity.json"),
  )

  const { keypair, created } = nodeIdentity(identityPath)
  console.log(
    `device ${encodeEd25519PublicKey(keypair.publicKey)} (${identityPath}${created ? ", new" : ", reused"})`,
  )

  const invite = pairCode ? parseInvite(pairCode) : undefined
  // The same base64 trap the invite guards against: a pasted epk is usually the
  // base64URL form from the pairing URI (`-`/`_`), while the relay keys its
  // allow-lists by the canonical padded form. Pass it through verbatim and
  // `rooms_check` answers `unknown_peer` for a machine that is paired.
  const machineEpk =
    invite?.epk ?? canonicalizeEd25519PublicKey(peerArg!) ?? peerArg!
  const client = new SessionClient(relay, keypair, {
    onRelayIdentity: (pubkey) => console.log(`relay identity: ${pubkey}`),
  })

  console.log(`connecting to ${relay} …`)
  await client.connect()

  // The machine's own report from `pair_ok` (harness version, caps…). Absent on
  // a re-run that skipped pairing — the room list carries what matters then.
  let machineInfo: unknown
  if (invite) {
    console.log(`pairing (${machineEpk.slice(0, 8)}…) …`)
    const verdict = await client.pairAwaited(
      invite,
      arg("name") ?? "web-client fixture dump",
    )
    if (!verdict.ok) {
      console.error(
        `pairing refused: ${verdict.detail} — the code is single-use and short-` +
          "lived; run `/unbien pair --ttl 600` and paste it at once",
      )
      client.close()
      return 1
    }
    machineInfo = verdict.machine
  } else {
    // No code needed: pairing is per-machine and persists, so a device already
    // in the machine's peers.json can address it directly.
    client.setRoutingPeer(machineEpk)
  }

  // `unknown_peer` here is usually a RACE, not a refusal: the extension sends
  // `pair_ok` right after `addPeer`, but the signed allow-list re-push that
  // makes `rooms_check` pass is fire-and-forget (`refreshPairingsCache()` →
  // `listPeers().then(push)`, extension/src/index.ts). A script fast enough to
  // ask for rooms in the same tick gets refused; a browser, with a human click
  // in the way, never notices. Retry briefly rather than declaring failure —
  // and if it STILL says unknown_peer, this device really is not in the list.
  let rooms = await client.listRooms(machineEpk)
  for (let attempt = 1; rooms.status !== "ok" && attempt <= 8; attempt++) {
    if (rooms.status !== "unknown_peer") break
    console.log(`rooms_check: unknown_peer — retrying (${attempt}/8)…`)
    await new Promise((r) => setTimeout(r, 400))
    rooms = await client.listRooms(machineEpk)
  }
  console.log(describeRooms(machineEpk, rooms))
  if (rooms.status !== "ok") {
    console.error(`cannot list rooms: ${rooms.status}`)
    client.close()
    return 1
  }

  // The invite's `rm` is the room pi announced at pair time; with no invite the
  // caller names it, and a single-room machine needs no name.
  const wanted = arg("room") ?? invite?.roomId ?? rooms.rooms[0]?.room_id ?? ""
  const room = rooms.rooms.find((candidate) => candidate.room_id === wanted)
  if (!room) {
    console.error(
      `room ${wanted} is not in this machine's list — pass --room <id> from the list above`,
    )
    client.close()
    return 1
  }

  client.setRoutingPeer(machineEpk)
  client.setRoom(room.room_id)
  // The launcher daemon advertises a control room (`is_daemon`) that answers
  // `session_launch` and friends but NOT `get_entries` — a dump aimed at it just
  // hangs until the rpc times out, which reads like an empty session. Say so.
  if ((room.caps ?? []).includes("is_daemon") && !flag("force")) {
    console.error(
      `room ${room.room_id} is the launcher's control room (cap is_daemon): it ` +
        "serves session_launch, not get_entries. Pick a pi session's room " +
        "(--room <id> from the list above), or pass --force to try anyway.",
    )
    client.close()
    return 1
  }

  // The first frame to a trusted peer is what triggers the extension's attach.
  client.requestSync()

  // Paged by hand rather than through `getEntries()`, which swallows a failed
  // page: a machine that never answers then looks like a session with no
  // history, when the honest reading is "the rpc timed out".
  const entries: unknown[] = []
  let cursor: string | undefined
  let leafId: string | undefined
  for (let page = 0; page < maxPages; page++) {
    let data: { entries?: unknown[]; leafId?: string } | undefined
    try {
      data = await client.request<{ entries?: unknown[]; leafId?: string }>(
        "get_entries",
        cursor ? { since: cursor } : {},
        20_000,
      )
    } catch (err) {
      if (page === 0) {
        console.error(
          `get_entries failed on the first page: ${(err as Error).message} — ` +
            "this room's machine is not answering the rpc (a daemon control room, " +
            "or an extension that is connected but wedged)",
        )
        client.close()
        return 1
      }
      console.log(`walk stopped at page ${page}: ${(err as Error).message}`)
      break
    }
    const pageEntries = data?.entries ?? []
    leafId = data?.leafId
    if (pageEntries.length === 0 || !leafId) break
    entries.push(...pageEntries)
    if (leafId === cursor) break // the walk is spinning on one leaf
    cursor = leafId
  }
  console.log(`walked ${entries.length} entries (leaf ${leafId ?? "none"})`)

  const state = await client
    .request<Record<string, unknown>>("get_state")
    .catch(() => undefined)

  const fixture = {
    fetchedAt: new Date().toISOString(),
    relay,
    peer: machineEpk,
    room: {
      roomId: room.room_id,
      name: room.name,
      cwd: room.cwd,
      caps: room.caps,
      parent: room.parent,
    },
    // The machine's caps matter for reading a fixture later: a machine without
    // `images` never sent image blocks, so their absence proves nothing.
    machine: machineInfo ?? { rooms: rooms.rooms },
    state,
    leafId,
    entries,
  }

  // The live plane: whatever the machine pushes from here on is recorded, one
  // envelope per line. Subscribing AFTER the walk is deliberate — the walk's own
  // replay frames are not live, and mixing them in would make a fixture that
  // claims to test streaming but tests attach instead.
  const watchSeconds = Number(arg("watch") ?? 0)
  if (watchSeconds > 0) {
    const watchOut = resolve(arg("watch-out") ?? "/tmp/unbien-live.jsonl")
    const frames: unknown[] = []
    const counts = new Map<string, number>()
    client.on("envelope", (env) => {
      frames.push(env)
      const rpc = env.rpc as Record<string, unknown> | undefined
      const evt = env.evt as Record<string, unknown> | undefined
      const key =
        rpc && typeof rpc.type === "string"
          ? `rpc:${rpc.type}`
          : evt && typeof evt.channel === "string"
            ? `evt:${evt.channel}`
            : "other"
      counts.set(key, (counts.get(key) ?? 0) + 1)
    })
    console.log(
      `watching for ${watchSeconds}s — drive the session now (a turn, a tool call, a panel).`,
    )
    const started = Date.now()
    while (Date.now() - started < watchSeconds * 1000) {
      await new Promise((r) => setTimeout(r, 5000))
      console.log(
        `  ${frames.length} frames, ${((Date.now() - started) / 1000) | 0}s`,
      )
    }
    mkdirSync(dirname(watchOut), { recursive: true })
    writeFileSync(watchOut, frames.map((f) => JSON.stringify(f)).join("\n"))
    console.log(`wrote ${watchOut} (${frames.length} frames)`)
    for (const [key, n] of [...counts].sort((a, b) => b[1] - a[1])) {
      console.log(`  ${n}× ${key}`)
    }
  }

  if (flag("include-panels")) {
    // Panels ride `session_sync` notifications rather than `get_entries`, so a
    // fixture without them cannot test the subagent/plan/ask fold.
    const panels: unknown[] = []
    client.on("envelope", (env) => {
      const rpc = env.rpc as Record<string, unknown> | undefined
      if (rpc && typeof rpc.type === "string") panels.push(rpc)
    })
    client.requestSync()
    await new Promise((r) => setTimeout(r, 2500))
    Reflect.set(fixture, "panels", panels)
    console.log(`captured ${panels.length} panel frames`)
  }

  mkdirSync(dirname(out), { recursive: true })
  writeFileSync(out, JSON.stringify(fixture, null, 2))
  console.log(
    `wrote ${out} (${(JSON.stringify(fixture).length / 1024) | 0} KB)`,
  )
  client.close()
  return entries.length > 0 ? 0 : 1
}

main()
  .then((code) => process.exit(code))
  .catch((err) => {
    console.error(err instanceof Error ? `${err.name}: ${err.message}` : err)
    process.exit(1)
  })
